import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Auth.css';
import './BookingManagement.css';

const Dashboard = ({ user, onLogout }) => {
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [bookingSuccess, setBookingSuccess] = useState(false);
  const [bookingDetails, setBookingDetails] = useState(null);
  const [bookings, setBookings] = useState([]);
  const [searchRef, setSearchRef] = useState('');
  const [searchResult, setSearchResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [activeTab, setActiveTab] = useState('movies'); // 'movies', 'myBookings', 'search'

  const movies = [
    {
      id: 1,
      title: 'Avengers: Endgame',
      genre: 'Action',
      duration: '3h 1m',
      rating: 'PG-13',
      description: 'The epic conclusion to the Infinity Saga.',
      price: 12.99
    },
    {
      id: 2,
      title: 'The Batman',
      genre: 'Action, Crime',
      duration: '2h 56m',
      rating: 'PG-13',
      description: 'The Dark Knight of Gotham City begins his war on crime.',
      price: 11.99
    },
    {
      id: 3,
      title: 'Spider-Man: No Way Home',
      genre: 'Action, Adventure',
      duration: '2h 28m',
      rating: 'PG-13',
      description: 'Spider-Man seeks the help of Doctor Strange when his secret identity is revealed.',
      price: 13.99
    },
    {
      id: 4,
      title: 'Dune',
      genre: 'Sci-Fi',
      duration: '2h 35m',
      rating: 'PG-13',
      description: 'A noble family becomes embroiled in a war for control over the galaxy\'s most valuable asset.',
      price: 12.49
    }
  ];

  // Fetch user's bookings
  const fetchUserBookings = async () => {
    if (!user) return;

    setLoading(true);
    setMessage('');
    try {
      const response = await fetch(`http://localhost:5000/api/bookings/user/${user.id}`);
      const data = await response.json();

      if (data.success) {
        setBookings(data.data);
        if (data.data.length === 0) {
          setMessage('You have no bookings yet.');
        }
      } else {
        setMessage('Failed to load bookings');
      }
    } catch (error) {
      console.error('Failed to fetch bookings:', error);
      setMessage('Failed to load bookings. Please check your connection.');
    } finally {
      setLoading(false);
    }
  };

  // Search booking by reference number
  const searchBooking = async () => {
    if (!searchRef.trim()) {
      setMessage('Please enter a reference number');
      return;
    }

    setLoading(true);
    setMessage('');
    try {
      const response = await fetch(`http://localhost:5000/api/bookings/search/${searchRef}`);
      const data = await response.json();

      if (data.success) {
        setSearchResult(data.data);
        setMessage('Booking found successfully!');
      } else {
        setSearchResult(null);
        setMessage('Booking not found');
      }
    } catch (error) {
      console.error('Search failed:', error);
      setMessage('Search failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Cancel booking
  const cancelBooking = async (referenceNumber) => {
    if (!window.confirm('Are you sure you want to cancel this booking?')) return;

    setMessage('');
    try {
      const response = await fetch(`http://localhost:5000/api/bookings/cancel/${referenceNumber}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ userId: user?.id })
      });

      const data = await response.json();

      if (data.success) {
        setMessage('Booking cancelled successfully!');
        // Refresh bookings
        if (activeTab === 'myBookings') {
          fetchUserBookings();
        } else {
          setSearchResult(null);
          setSearchRef('');
        }
      } else {
        setMessage(data.message || 'Failed to cancel booking');
      }
    } catch (error) {
      console.error('Cancellation failed:', error);
      setMessage('Failed to cancel booking. Please try again.');
    }
  };

  // Clear search
  const clearSearch = () => {
    setSearchRef('');
    setSearchResult(null);
    setMessage('');
  };

  const handleBookTicket = (movie) => {
    setSelectedMovie(movie);
    setBookingSuccess(false);
    setBookingDetails(null);
  };

  const confirmBooking = async () => {
    if (selectedMovie) {
      try {
        const token = localStorage.getItem('token');
        const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000';

        const bookingData = {
          userId: user.id,
          userName: user.username,
          userEmail: user.email,
          movieTitle: selectedMovie.title,
          movieId: selectedMovie.id,
          theater: 'PVR Cinemas',
          showTime: new Date(Date.now() + 24 * 60 * 60 * 1000), // Tomorrow
          seats: ['A1', 'A2'],
          totalAmount: selectedMovie.price * 2
        };

        console.log('Sending booking request:', bookingData);

        const response = await axios.post(`${API_BASE_URL}/api/bookings`, bookingData, {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        });

        if (response.data.success) {
          setBookingDetails(response.data.booking);
          setBookingSuccess(true);
          // Refresh bookings after successful booking
          fetchUserBookings();

          setTimeout(() => {
            setSelectedMovie(null);
            setBookingSuccess(false);
          }, 5000);
        }
      } catch (error) {
        console.error('Booking API error:', error);
        // Fallback to simulated booking if API fails
        const booking = {
          id: Date.now(),
          movieTitle: selectedMovie.title,
          userName: user.username,
          bookingDate: new Date(),
          showTime: new Date(Date.now() + 24 * 60 * 60 * 1000),
          seats: ['A1', 'A2'],
          totalAmount: selectedMovie.price * 2,
          referenceNumber: 'REF' + Date.now().toString().slice(-6),
          status: 'confirmed'
        };

        setBookingDetails(booking);
        setBookingSuccess(true);

        setTimeout(() => {
          setSelectedMovie(null);
          setBookingSuccess(false);
        }, 5000);
      }
    }
  };

  const cancelBookingModal = () => {
    setSelectedMovie(null);
    setBookingSuccess(false);
    setBookingDetails(null);
  };

  useEffect(() => {
    if (activeTab === 'myBookings' && user) {
      fetchUserBookings();
    } else {
      setMessage('');
    }
  }, [activeTab, user]);

  const formatDate = (dateString) => {
    try {
      return new Date(dateString).toLocaleString('en-IN', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (error) {
      return 'Invalid Date';
    }
  };

  const formatCurrency = (amount) => {
    return `₹${amount?.toLocaleString('en-IN') || '0'}`;
  };

  const BookingCard = ({ booking }) => (
    <div className={`booking-card ${booking.status}`}>
      <div className="booking-header">
        <div>
          <h3>Reference: {booking.referenceNumber}</h3>
          <p className="booking-id">ID: {booking._id || booking.bookingId}</p>
        </div>
        <span className={`status-badge ${booking.status}`}>
          {booking.status?.toUpperCase() || 'UNKNOWN'}
        </span>
      </div>

      <div className="booking-details">
        <div className="detail-row">
          <span className="label">Movie:</span>
          <span className="value">{booking.movieTitle || booking.movie || 'Unknown Movie'}</span>
        </div>
        <div className="detail-row">
          <span className="label">Theater:</span>
          <span className="value">{booking.theater || 'Unknown Theater'}</span>
        </div>
        <div className="detail-row">
          <span className="label">Show Time:</span>
          <span className="value">{formatDate(booking.showTime)}</span>
        </div>
        <div className="detail-row">
          <span className="label">Seats:</span>
          <span className="value">
            {Array.isArray(booking.seats) ? booking.seats.join(', ') : 'N/A'}
          </span>
        </div>
        <div className="detail-row">
          <span className="label">Amount:</span>
          <span className="value amount">{formatCurrency(booking.totalAmount || booking.total)}</span>
        </div>
        <div className="detail-row">
          <span className="label">Booked On:</span>
          <span className="value">{formatDate(booking.bookingDate)}</span>
        </div>
        {booking.userName && (
          <div className="detail-row">
            <span className="label">Booked By:</span>
            <span className="value">{booking.userName}</span>
          </div>
        )}
      </div>

      {booking.status === 'confirmed' && (
        <div className="booking-actions">
          <button 
            className="cancel-btn"
            onClick={() => cancelBooking(booking.referenceNumber)}
          >
            Cancel Booking
          </button>
        </div>
      )}

      {booking.status === 'cancelled' && booking.cancelledAt && (
        <div className="cancellation-info">
          <p>Cancelled on: {formatDate(booking.cancelledAt)}</p>
        </div>
      )}
    </div>
  );

  return (
    <div className="container">
      <div className="card">
        {/* Header Section */}
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          marginBottom: '20px',
          flexWrap: 'wrap',
          gap: '20px'
        }}>
          <div>
            <h1 style={{ color: '#333', marginBottom: '10px' }}>
              Welcome to Movie Ticket App!
            </h1>
            <p style={{ color: '#666', fontSize: '18px' }}>
              Hello, <strong>{user?.username}</strong>! Ready to book some movies?
            </p>
          </div>
          <button 
            onClick={onLogout} 
            className="btn btn-secondary"
            style={{ minWidth: '120px' }}
          >
            Logout
          </button>
        </div>

        {/* Navigation Tabs */}
        <div style={{
          display: 'flex',
          gap: '10px',
          marginBottom: '30px',
          background: '#f8f9fa',
          padding: '10px',
          borderRadius: '10px',
          flexWrap: 'wrap'
        }}>
          <button 
            className={`tab-btn ${activeTab === 'movies' ? 'active' : ''}`}
            onClick={() => setActiveTab('movies')}
            style={{
              padding: '12px 24px',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontSize: '16px',
              fontWeight: '500',
              transition: 'all 0.3s ease',
              background: activeTab === 'movies' ? '#667eea' : 'transparent',
              color: activeTab === 'movies' ? 'white' : '#666'
            }}
          >
            🎥 Movies
          </button>
          <button 
            className={`tab-btn ${activeTab === 'myBookings' ? 'active' : ''}`}
            onClick={() => setActiveTab('myBookings')}
            style={{
              padding: '12px 24px',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontSize: '16px',
              fontWeight: '500',
              transition: 'all 0.3s ease',
              background: activeTab === 'myBookings' ? '#667eea' : 'transparent',
              color: activeTab === 'myBookings' ? 'white' : '#666'
            }}
          >
            🎫 My Bookings
          </button>
          <button 
            className={`tab-btn ${activeTab === 'search' ? 'active' : ''}`}
            onClick={() => setActiveTab('search')}
            style={{
              padding: '12px 24px',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontSize: '16px',
              fontWeight: '500',
              transition: 'all 0.3s ease',
              background: activeTab === 'search' ? '#667eea' : 'transparent',
              color: activeTab === 'search' ? 'white' : '#666'
            }}
          >
            🔍 Search Ticket
          </button>
        </div>

        {/* Messages */}
        {message && (
          <div style={{
            padding: '12px 16px',
            borderRadius: '8px',
            marginBottom: '20px',
            fontWeight: '500',
            background: message.includes('success') ? '#d4edda' : '#f8d7da',
            color: message.includes('success') ? '#155724' : '#721c24',
            border: `1px solid ${message.includes('success') ? '#c3e6cb' : '#f5c6cb'}`
          }}>
            {message}
          </div>
        )}

        {/* Booking Success Message */}
        {bookingSuccess && bookingDetails && (
          <div className="card" style={{
            background: '#d4edda',
            border: '1px solid #c3e6cb',
            color: '#155724',
            marginBottom: '20px'
          }}>
            <h3>🎉 Booking Confirmed!</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginTop: '15px' }}>
              <div><strong>Reference:</strong> {bookingDetails.referenceNumber || bookingDetails.bookingId}</div>
              <div><strong>Movie:</strong> {bookingDetails.movieTitle || bookingDetails.movie}</div>
              <div><strong>Show Time:</strong> {formatDate(bookingDetails.showTime)}</div>
              <div><strong>Seats:</strong> {bookingDetails.seats.join(', ')}</div>
              <div><strong>Total:</strong> {formatCurrency(bookingDetails.totalAmount || bookingDetails.total)}</div>
            </div>
            <p style={{ marginTop: '15px', fontWeight: 'bold' }}>
              Enjoy your movie! 🍿
            </p>
          </div>
        )}

        {/* Booking Modal */}
        {selectedMovie && !bookingSuccess && (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            zIndex: 1000
          }}>
            <div className="card" style={{ maxWidth: '500px', width: '90%' }}>
              <h2>Book Tickets - {selectedMovie.title}</h2>
              <div style={{ margin: '20px 0' }}>
                <p><strong>Genre:</strong> {selectedMovie.genre}</p>
                <p><strong>Duration:</strong> {selectedMovie.duration}</p>
                <p><strong>Rating:</strong> {selectedMovie.rating}</p>
                <p><strong>Price per ticket:</strong> ${selectedMovie.price}</p>
                <p><strong>Description:</strong> {selectedMovie.description}</p>
              </div>

              <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                <button 
                  className="btn btn-primary"
                  onClick={confirmBooking}
                >
                  Confirm Booking (2 tickets - ${(selectedMovie.price * 2).toFixed(2)})
                </button>
                <button 
                  className="btn btn-secondary"
                  onClick={cancelBookingModal}
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Movies Tab Content */}
        {activeTab === 'movies' && (
          <div className="card">
            <h2 style={{ marginBottom: '20px', color: '#333' }}>🎥 Now Showing</h2>
            <div style={{ 
              display: 'grid', 
              gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', 
              gap: '25px' 
            }}>
              {movies.map(movie => (
                <div 
                  key={movie.id} 
                  style={{
                    border: '1px solid #e1e5e9',
                    borderRadius: '15px',
                    padding: '20px',
                    textAlign: 'center',
                    background: 'white',
                    boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                    transition: 'transform 0.2s ease, box-shadow 0.2s ease'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = 'translateY(-5px)';
                    e.currentTarget.style.boxShadow = '0 8px 15px rgba(0, 0, 0, 0.2)';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = '0 4px 6px rgba(0, 0, 0, 0.1)';
                  }}
                >
                  <div style={{
                    width: '100%',
                    height: '200px',
                    borderRadius: '10px',
                    marginBottom: '15px',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    color: 'white',
                    fontWeight: 'bold',
                    fontSize: '16px'
                  }}>
                    🎬 {movie.title}
                  </div>
                  <h3 style={{ 
                    marginBottom: '10px', 
                    color: '#333',
                    fontSize: '20px'
                  }}>
                    {movie.title}
                  </h3>
                  <p style={{ color: '#666', marginBottom: '5px' }}>
                    <strong>Genre:</strong> {movie.genre}
                  </p>
                  <p style={{ color: '#666', marginBottom: '5px' }}>
                    <strong>Duration:</strong> {movie.duration} • <strong>Rating:</strong> {movie.rating}
                  </p>
                  <p style={{ color: '#666', marginBottom: '10px', fontWeight: 'bold' }}>
                    <strong>Price:</strong> ${movie.price}
                  </p>
                  <p style={{ 
                    color: '#888', 
                    fontSize: '14px',
                    marginBottom: '15px',
                    fontStyle: 'italic'
                  }}>
                    {movie.description}
                  </p>
                  <button 
                    className="btn btn-primary" 
                    style={{ width: '100%' }}
                    onClick={() => handleBookTicket(movie)}
                  >
                    🎟️ Book Tickets
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* My Bookings Tab Content */}
        {activeTab === 'myBookings' && (
          <div className="card">
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h2 style={{ color: '#333', margin: 0 }}>My Bookings ({bookings.length})</h2>
              <button 
                className="btn btn-primary"
                onClick={fetchUserBookings}
                disabled={loading}
                style={{ minWidth: '120px' }}
              >
                {loading ? 'Loading...' : '🔄 Refresh'}
              </button>
            </div>

            {loading ? (
              <div style={{ textAlign: 'center', padding: '40px', color: '#666' }}>
                <div style={{
                  border: '3px solid #f3f3f3',
                  borderTop: '3px solid #667eea',
                  borderRadius: '50%',
                  width: '40px',
                  height: '40px',
                  animation: 'spin 1s linear infinite',
                  margin: '0 auto 20px'
                }}></div>
                Loading your bookings...
              </div>
            ) : bookings.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '40px', color: '#666' }}>
                <h3>No Bookings Yet</h3>
                <p>You haven't made any bookings yet. Start by booking a movie!</p>
              </div>
            ) : (
              <div style={{ display: 'grid', gap: '20px' }}>
                {bookings.map(booking => (
                  <BookingCard key={booking._id || booking.bookingId} booking={booking} />
                ))}
              </div>
            )}
          </div>
        )}

        {/* Search Tab Content */}
        {activeTab === 'search' && (
          <div className="card">
            <h2 style={{ marginBottom: '20px', color: '#333' }}>🔍 Search Ticket by Reference Number</h2>

            <div style={{ display: 'flex', gap: '10px', marginBottom: '30px', alignItems: 'center', flexWrap: 'wrap' }}>
              <input
                type="text"
                placeholder="Enter reference number (e.g., REF001)"
                value={searchRef}
                onChange={(e) => setSearchRef(e.target.value.toUpperCase())}
                onKeyPress={(e) => e.key === 'Enter' && searchBooking()}
                style={{
                  flex: '1',
                  padding: '12px',
                  border: '2px solid #e0e0e0',
                  borderRadius: '8px',
                  fontSize: '16px',
                  minWidth: '200px'
                }}
              />
              <button 
                onClick={searchBooking} 
                disabled={loading || !searchRef.trim()}
                className="btn btn-primary"
                style={{ minWidth: '120px' }}
              >
                {loading ? 'Searching...' : 'Search'}
              </button>
              {searchRef && (
                <button 
                  onClick={clearSearch}
                  className="btn btn-secondary"
                >
                  Clear
                </button>
              )}
            </div>

            {searchResult && (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
                  <h3 style={{ color: '#333', margin: 0 }}>Search Result</h3>
                  <button onClick={clearSearch} className="btn btn-secondary">× Clear</button>
                </div>
                <BookingCard booking={searchResult} />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
